const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>Number(n||0).toLocaleString('ko-KR')+'원';
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const shops=window.SEOUL_SHOPS;
const samples=window.SEOUL_MENU_DEFS.map(([id,shop,name,price,stock,image,desc],i)=>({id,shop,name,price,stock,image:'assets/'+image+'.jpg',desc,closing:'18:00',date:day(),publishedAt:Date.parse(day()+'T00:00:00+09:00')+(window.SEOUL_MENU_DEFS.length-i)*60000,likes:0,sample:true}));
const home={lat:37.5446,lng:127.0445};
const saved=(()=>{try{return JSON.parse(localStorage.getItem('hangolmok-v2')||'null')}catch{return null}})();
const old=(()=>{try{return JSON.parse(localStorage.getItem('hangolmok-v1')||'null')}catch{return null}})();
let state=saved||{mode:'guest',tab:'feed',font:1,menus:old?.menus?.length?old.menus.map(m=>({...m,closing:m.closing||'18:00',sample:!m.custom})):samples,likes:old?.liked||[],orders:[],cart:[],location:null,locationStatus:'demo'};
state.menus=Array.isArray(state.menus)?state.menus:samples;
state.likes=Array.isArray(state.likes)?state.likes:[];
state.orders=Array.isArray(state.orders)?state.orders:[];
state.orderStatuses=state.orderStatuses&&typeof state.orderStatuses==='object'?state.orderStatuses:{};
state.demoOwnerOrders=Array.isArray(state.demoOwnerOrders)?state.demoOwnerOrders:null;
state.cart=Array.isArray(state.cart)?state.cart:[];
state.font=Number(state.font)||1;
const DATA_VERSION=5;let migrated=false;
if(state.seedVersion!==DATA_VERSION||!state.menus.some(m=>m.date===day())){const custom=state.menus.filter(m=>!m.sample&&m.date===day());state.menus=[...custom,...samples];state.cart=[];state.seedVersion=DATA_VERSION;migrated=true;}
state.area=state.area||'';
let kakaoMap=null;let storyFilter='',settingsOpen=false;let feedQuery='',mapQuery='',aiText='',aiResult=null,draft=null,photo=null,selectedShop=null,recognition=null;
const persist=()=>{try{localStorage.setItem('hangolmok-v2',JSON.stringify(state))}catch{toast('이 기기의 저장 공간이 부족합니다.')}};
if(migrated)persist();
const shop=id=>shops.find(s=>s.id===id)||shops[0];
const active=()=>state.menus.filter(m=>m.date===day());
const OWNER_SHOP_ID='bake';
const ownerMenus=()=>active().filter(m=>m.shop===OWNER_SHOP_ID);
const orderNumber=o=>String(o.id).slice(-6);
const ownerOrders=()=>[...state.orders.filter(o=>o.items.some(i=>i.shop===OWNER_SHOP_ID)),...state.demoOwnerOrders].sort((a,b)=>b.id-a.id);
const orderStatus=o=>state.orderStatuses[o.id]||'waiting';
const statusLabel=s=>({waiting:'접수 대기',accepted:'주문 수락',preparing:'준비 중',ready:'준비 완료'})[s]||'접수 대기';
function ownerBanner(){const s=shop(OWNER_SHOP_ID);return `<div class="owner-shop-banner"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${esc(s.area)} · 내 가게</small></span></div>`}
const image=m=>esc(m.image||'assets/croissant.jpg');
const distance=(a,b)=>{const r=Math.PI/180,x=(b.lat-a.lat)*r,y=(b.lng-a.lng)*r,z=Math.sin(x/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(y/2)**2;return 6371*2*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))};
const center=()=>state.area&&state.area!=='all'?shop(state.area):state.location||home;
const nearby=()=>state.area==='all'?shops:shops.filter(s=>distance(center(),s)<=3);
const nearbyMenus=()=>active().filter(m=>nearby().some(s=>s.id===m.shop));
const hhmm=d=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);
if(!state.demoOwnerOrders){const now=Date.now();state.demoOwnerOrders=[{id:now-120000,date:day()+' '+hhmm(new Date(now-120000)),items:[{id:1,shop:OWNER_SHOP_ID,name:'딸기 크루아상',qty:2,price:4500},{id:61,shop:OWNER_SHOP_ID,name:'성수 소금빵',qty:1,price:3200}],total:12200,stops:[{id:OWNER_SHOP_ID,name:'오후의 빵집',address:shop(OWNER_SHOP_ID).address,pickup:hhmm(new Date(now+24*60000)),items:['딸기 크루아상 × 2','성수 소금빵 × 1']}],sample:true},{id:now-300000,date:day()+' '+hhmm(new Date(now-300000)),items:[{id:4,shop:OWNER_SHOP_ID,name:'버터 스콘',qty:1,price:3500},{id:64,shop:OWNER_SHOP_ID,name:'초코 휘낭시에',qty:2,price:2800}],total:9100,stops:[{id:OWNER_SHOP_ID,name:'오후의 빵집',address:shop(OWNER_SHOP_ID).address,pickup:hhmm(new Date(now+18*60000)),items:['버터 스콘 × 1','초코 휘낭시에 × 2']}],sample:true}];persist()}
const icon=name=>{
 const paths={
  feed:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  map:'<path d="M3 6 9 3l6 3 6-3v15l-6 3-6-3-6 3V6Z"/><path d="M9 3v15M15 6v15"/>',
  orders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 8h6M9 12h6"/>',
  register:'<path d="M12 4v16M4 12h16"/>',
  ownerOrders:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 8h6M9 12h6"/>',
  manage:'<path d="M4 6h16M4 12h16M4 18h16"/>'
 };
 return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.feed}</svg>`
};
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3300)}
function say(t){if(!window.speechSynthesis){toast('이 브라우저는 음성 안내를 지원하지 않습니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ko-KR';u.rate=.9;speechSynthesis.speak(u)}
function pageSpeech(){
 const titles={feed:'피드',map:'지도',orders:'내 주문',register:'등록',ownerOrders:'주문',manage:'관리'};
 const parts=[titles[state.tab]+' 화면입니다.'];
 if(state.tab==='feed'){const items=visibleFeed();parts.push((state.area==='all'?'서울 전체 메뉴 ':'근처 메뉴 ')+items.length+'개.');parts.push(...items.slice(0,6).map(m=>shop(m.shop).name+'의 '+m.name+', '+won(m.price)+', 재고 '+m.stock+'개.'))}
 if(state.tab==='map'){const list=visibleMapShops();parts.push((state.area==='all'?'서울 전체 가게 ':'반경 3킬로미터 내 가게 ')+list.length+'곳.');parts.push(...list.map(s=>state.area==='all'?s.area+'의 '+s.name+'.':s.name+', 약 '+distance(center(),s).toFixed(1)+'킬로미터.'))}
 if(state.tab==='orders'){parts.push('주문 '+state.orders.length+'건.');parts.push(...state.orders.slice(0,3).map(o=>'픽업 대기 주문, '+won(o.total)+', '+o.stops.length+'곳 픽업.'))}
 if(state.tab==='register')parts.push('먼저 사진을 촬영하거나 올리고, 상품의 이름, 가격, 재고량, 마감 시간을 말해 주세요. 초안을 확인한 다음 등록할 수 있습니다.');
 if(state.tab==='ownerOrders')parts.push('오후의 빵집 주문 '+ownerOrders().length+'건. 주문을 확인하고 수락한 뒤 준비 상태를 변경할 수 있습니다.');
 if(state.tab==='manage'){parts.push('오후의 빵집 오늘의 메뉴 '+ownerMenus().length+'개.');parts.push(...ownerMenus().slice(0,7).map(m=>m.name+', '+won(m.price)+', 재고 '+m.stock+'개.'))}
 say(parts.join(' '))
}
function render(){document.documentElement.style.setProperty('--scale',state.font);const owner=state.mode==='owner';const tabs=owner?[['register','등록'],['ownerOrders','주문'],['manage','관리']]:[['feed','피드'],['map','지도'],['orders','내 주문']];if(!tabs.some(([id])=>id===state.tab))state.tab=owner?'register':'feed';
 $('#app').innerHTML=`<div class="site"><header class="site-header"><div class="header-main"><button class="brand" data-action="home" aria-label="마감한끼 홈"><span class="brand-mark">ㅎ</span><span>마감한끼</span></button><div class="header-actions"><div class="settings-menu"><button class="settings-button" data-action="settings" aria-label="설정" aria-expanded="${settingsOpen}" aria-controls="settings-panel"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.5 13.3 5l2-.3.7 1.8 1.9.8-.3 2 1.5 1.2-1 1.8 1 1.8-1.5 1.2.3 2-1.9.8-.7 1.8-2-.3L12 21l-1.3-1.5-2 .3-.7-1.8-1.9-.8.3-2L4.9 14l1-1.8-1-1.8 1.5-1.2-.3-2L8 6.5l.7-1.8 2 .3L12 3.5Z"/><circle cx="12" cy="12.2" r="2.6"/></svg><span>설정</span></button><div id="settings-panel" class="settings-panel" role="group" aria-label="접근성 설정" ${settingsOpen?'':'hidden'}><strong>접근성 설정</strong><div class="settings-row"><span>글자 크기</span><div class="font-tools" aria-label="글자 크기 조절"><button data-action="font-down" aria-label="글자 작게">가−</button><button data-action="font-up" aria-label="글자 크게">가＋</button></div></div><button class="voice-btn" data-action="speak" aria-label="현재 화면 음성 안내">◖)) <span>현재 화면 음성 안내</span></button></div></div><button class="mode-switch" data-action="mode">${owner?'손님 ver':'사장 ver'} <span aria-hidden="true">↗</span></button></div></div></header><main id="main" class="main ${state.tab}">${content()}</main><nav class="tabbar" aria-label="${owner?'사장님 메뉴':'손님 메뉴'}">${tabs.map(([id,label])=>`<button data-action="tab" data-value="${id}" class="${state.tab===id?'active':''}" aria-current="${state.tab===id?'page':'false'}"><span class="tab-icon" aria-hidden="true">${icon(id)}</span><span>${label}</span></button>`).join('')}</nav></div>`;if(state.tab==='map')requestAnimationFrame(initMap)}
function heading(kicker,title,sub=''){return `<div class="page-heading"><span class="kicker">${kicker}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function content(){return ({feed:feedPage,map:mapPage,orders:ordersPage,register:registerPage,ownerOrders:ownerOrdersPage,manage:managePage})[state.tab]()}
function locationNote(){
 const areas=[...new Map(shops.map(s=>[s.area,s])).values()];
 return `<div class="location-note"><div class="location-actions"><label class="area-select-label">지역 보기<select id="area-select" aria-label="서울 지역 선택"><option value="" ${!state.area?'selected':''}>내 주변 3km</option><option value="all" ${state.area==='all'?'selected':''}>서울 전체</option>${areas.map(s=>`<option value="${s.id}" ${state.area===s.id?'selected':''}>${esc(s.area)}</option>`).join('')}</select></label><button data-action="locate">내 위치 사용</button></div></div>`
}
function visibleFeed(){return nearbyMenus().filter(m=>(!storyFilter||m.shop===storyFilter)).filter(m=>(m.name+' '+m.desc+' '+shop(m.shop).name).toLocaleLowerCase().includes(feedQuery.toLocaleLowerCase()))}
function card(m){const s=shop(m.shop),liked=state.likes.includes(m.id),inCart=state.cart.some(x=>x.id===m.id);return `<article class="post"><div class="post-top"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${esc(s.area)} · ${state.area==='all'?'서울 가상 가게':distance(center(),s).toFixed(1)+'km'}</small></span><span class="stock ${m.stock?'':'sold'}">${m.stock?'재고 '+m.stock+'개':'품절'}</span></div><img class="post-photo" src="${image(m)}" alt="${esc(m.name)} 사진" loading="lazy"><div class="post-actions"><button data-action="like" data-id="${m.id}" class="${liked?'liked':''}" aria-pressed="${liked}" aria-label="${esc(m.name)} 좋아요">${liked?'♥':'♡'} <span>${(m.likes||0)+(liked?1:0)}</span></button><button data-action="add" data-id="${m.id}" class="add-btn" ${!m.stock?'disabled':''}>${inCart?'한 개 더 담기':'담기 ＋'}</button></div><div class="post-info"><div class="title-line"><h2>${esc(m.name)}</h2><strong>${won(m.price)}</strong></div><p>${esc(m.desc)}</p><small>마감 ${esc(m.closing||'18:00')} · ${m.sample?'샘플 메뉴':'사장님 등록 메뉴'}</small></div></article>`}
function stories(){
 const latest=s=>Math.max(0,...active().filter(m=>m.shop===s.id).map(m=>m.publishedAt||(!m.sample&&Number(m.id)>1e12?Number(m.id):0)));
 const list=nearby().slice().sort((a,b)=>latest(b)-latest(a));
 requestAnimationFrame(updateStoryArrows);
 return `<div class="stories-wrap"><div class="stories" aria-label="가게별 피드, 좌우로 스크롤"><button class="story ${!storyFilter?'active':''}" data-action="story" data-value=""><span class="story-ring"><span class="story-all">◎</span></span><span>전체</span></button>${list.map(s=>`<button class="story ${storyFilter===s.id?'active':''}" data-action="story" data-value="${s.id}"><span class="story-ring"><img src="assets/${s.image}.jpg" alt=""></span><span>${esc(s.name)}</span></button>`).join('')}</div><button class="stories-prev" data-action="stories-prev" aria-label="이전 가게 보기" disabled>‹</button><button class="stories-next" data-action="stories-next" aria-label="다음 가게 보기">›</button></div><div class="feed-meta"><span>오늘의 메뉴</span><strong>${visibleFeed().length}개</strong></div>`
}
function feedPage(){return `<div class="feed-head"><button class="ai-button" data-action="ai-open">✧ AI 세트</button></div><label class="search-field"><span aria-hidden="true">⌕</span><input id="feed-search" type="search" placeholder="원하는 메뉴나 가게 검색" value="${esc(feedQuery)}" aria-label="메뉴 검색"></label>${locationNote()}${stories()}<div class="feed-list">${visibleFeed().map(card).join('')||`<div class="empty"><h2>표시할 메뉴가 없어요</h2><p>${state.locationStatus==='live'?'현재 위치에서 3km 이내의 등록된 샘플 가게가 없습니다.':'검색어를 바꾸거나 내 위치를 확인해 주세요.'}</p></div>`}</div>${state.cart.length?`<button class="floating-cart" data-action="cart">담은 메뉴 ${state.cart.reduce((n,x)=>n+x.qty,0)}개 · ${won(cartTotal())} <span>보기 →</span></button>`:''}<p class="demo-note">서울 전역의 가상 가게 ${shops.length}곳과 샘플 메뉴 ${samples.length}개를 사용하는 시연 화면입니다. 가격과 재고는 이 기기에만 저장됩니다.</p>`}
function visibleMapShops(){return nearby().filter(s=>{const q=mapQuery.toLocaleLowerCase();return !q||s.name.toLocaleLowerCase().includes(q)||active().some(m=>m.shop===s.id&&m.name.toLocaleLowerCase().includes(q))})}
function mapPage(){const c=center(),markers=visibleMapShops().map(s=>{const x=50+(s.lng-c.lng)*750,y=50-(s.lat-c.lat)*750;return `<button class="map-pin" data-action="shop" data-value="${s.id}" style="left:${Math.max(9,Math.min(91,x))}%;top:${Math.max(12,Math.min(87,y))}%" aria-label="${esc(s.name)} 정보">●<span>${esc(s.name)}</span></button>`}).join('');return `${heading('AROUND ME','서울 골목 지도',state.area==='all'?'서울 전역의 가상 가게 20곳을 둘러보세요.':'선택한 위치에서 반경 3km 안의 가게를 찾아보세요.')}<label class="search-field"><span aria-hidden="true">⌕</span><input id="map-search" type="search" placeholder="지도에서 메뉴 검색" value="${esc(mapQuery)}" aria-label="지도 메뉴 검색"></label>${locationNote()}<div class="map-canvas" role="group" aria-label="내 위치와 근처 가게를 표시한 안내 지도"><div class="street horizontal h1"></div><div class="street horizontal h2"></div><div class="street horizontal h3"></div><div class="street vertical v1"></div><div class="street vertical v2"></div><div class="street diagonal"></div><div class="radius-ring"></div><div id="kakao-map" class="kakao-map"></div><div class="you-pin" style="left:50%;top:50%" title="내 위치 또는 예시 위치">⌖<span>내 위치</span></div>${markers}<span class="map-attrib">위치 관계 안내 · 실제 지도 아님</span></div><div class="map-list"><h2>${state.area==='all'?'서울 전체':'3km 이내'} 가게 <span>${visibleMapShops().length}곳</span></h2>${visibleMapShops().map(s=>`<button data-action="shop" data-value="${s.id}" class="shop-row"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>${state.area==='all'?esc(s.area):distance(c,s).toFixed(1)+'km'} · 오늘 메뉴 ${active().filter(m=>m.shop===s.id).length}개</small></span><b>›</b></button>`).join('')||'<p class="muted">반경 안에 표시할 샘플 가게가 없습니다.</p>'}</div><p class="demo-note">서울 곳곳의 가상 가게와 예시 위치입니다. 실제 길찾기는 추후 연결됩니다.</p>`}
function ordersPage(){const likedShops=[...new Set(active().filter(m=>state.likes.includes(m.id)).map(m=>m.shop))];return `${heading('MY ALLEY','내 주문','주문 현황과 좋아하는 가게를 확인하세요.')}<section class="panel"><div class="panel-title"><h2>주문 현황</h2><span>${state.orders.length}건</span></div>${state.orders.length?state.orders.map(orderCard).join(''):'<div class="empty small"><h3>아직 주문이 없어요</h3><p>피드에서 메뉴를 담아 주문 흐름을 체험해 보세요.</p><button class="plain-button" data-action="tab" data-value="feed">피드로 가기 →</button></div>'}</section><section class="panel"><div class="panel-title"><h2>좋아요 남긴 가게</h2><span>${likedShops.length}곳</span></div>${likedShops.length?likedShops.map(id=>{const s=shop(id);return `<button class="shop-row" data-action="shop" data-value="${id}"><img src="assets/${s.image}.jpg" alt=""><span><strong>${esc(s.name)}</strong><small>좋아요 남긴 메뉴 ${active().filter(m=>m.shop===id&&state.likes.includes(m.id)).length}개</small></span><b>›</b></button>`}).join(''):'<p class="muted">좋아요를 누른 가게가 여기에 모여요.</p>'}</section><section class="panel review-panel"><h2>다녀온 골목, 어땠나요?</h2><p>방문 경험을 남기는 리뷰 기능은 추후 제공됩니다.</p><button class="outline-button" data-action="review">리뷰 작성하기</button></section>`}
function orderCard(o){const bakery=o.items.some(i=>i.shop===OWNER_SHOP_ID),status=bakery?statusLabel(orderStatus(o)):'픽업 대기';return `<div class="order-card"><div class="order-top"><strong>주문 #${orderNumber(o)}</strong><span>${status} · 데모</span></div><p>${o.items.map(i=>esc(i.name)+' × '+i.qty).join(' · ')}</p><strong>${won(o.total)}</strong><div class="order-bottom"><small>${esc(o.date)} · ${o.stops.length}곳 픽업</small><button data-action="route" data-id="${o.id}">지도에서 픽업 동선 보기 →</button></div></div>`}
function ownerOrdersPage(){const list=ownerOrders(),waiting=list.filter(o=>orderStatus(o)==='waiting').length;return `${heading('FOR SHOP OWNERS','들어온 주문',`오후의 빵집 주문 ${list.length}건 · 수락 대기 ${waiting}건`)}${ownerBanner()}<section class="panel"><div class="panel-title"><h2>주문 내역</h2><span>${list.length}건</span></div>${list.length?list.map(ownerOrderCard).join(''):'<div class="empty small"><h3>새 주문이 없어요</h3><p>오후의 빵집 메뉴가 주문되면 여기에 표시됩니다.</p></div>'}</section><p class="demo-note">예시 주문은 시연용입니다. 실제 주문과 상태 변경은 이 브라우저에만 저장됩니다.</p>`}
function ownerOrderCard(o){const items=o.items.filter(i=>i.shop===OWNER_SHOP_ID),stop=o.stops.find(s=>s.id===OWNER_SHOP_ID),status=orderStatus(o),next={waiting:['accepted','주문 수락'],accepted:['preparing','준비 시작'],preparing:['ready','준비 완료']}[status];return `<article class="owner-order-card"><div class="owner-order-top"><strong>주문 #${orderNumber(o)}</strong><span class="owner-status ${status}">${statusLabel(status)}</span></div><small>${esc(o.date)}${o.sample?' · 예시 주문':''}</small><div class="owner-order-items">${items.map(i=>`<div><span>${esc(i.name)}</span><b>× ${i.qty}</b></div>`).join('')}</div><div class="owner-eta"><span>고객 도착 예상</span><strong>${esc(stop?.pickup||'확인 중')}</strong></div>${next?`<button class="primary owner-order-action" data-action="owner-status" data-id="${o.id}" data-value="${next[0]}">${next[1]}</button>`:'<p class="owner-ready">픽업 준비가 완료됐어요.</p>'}</article>`}
function registerPage(){return `${heading('FOR SHOP OWNERS','오늘의 메뉴 등록','오후의 빵집에 새 메뉴를 등록하세요.')}${ownerBanner()}<div class="step-label"><span>01 사진</span><span>02 음성 설명</span><span>03 확인 후 등록</span></div><section class="panel register-panel"><h2>1. 상품 사진</h2><p>사진을 촬영하거나 기기에서 올려 주세요.</p><label class="upload-box"><input id="product-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="상품 사진 촬영 또는 업로드">${photo?`<img src="${photo}" alt="선택한 상품 사진"><strong>사진을 선택했어요 · 다시 선택 가능</strong>`:'<span class="camera-icon">▣</span><strong>촬영 또는 사진 올리기</strong><small>JPG, PNG, WebP · 최대 5MB</small>'}</label><h2>2. 상품 설명</h2><p>예: “딸기 크루아상 4,500원, 10개 남았고 오후 6시에 마감해요.”</p><div class="voice-input"><button data-action="dictate" class="mic-button" aria-label="음성 입력 시작">🎙 <span>음성으로 입력</span></button><span id="mic-status">마이크가 어려우면 아래에 직접 입력해 주세요.</span></div><textarea id="product-phrase" rows="4" placeholder="상품 이름, 가격, 재고량, 마감시간을 말하거나 입력하세요."></textarea><button class="primary" data-action="make-draft">등록 초안 만들기 →</button><p class="demo-note">현재 입력 분석은 규칙 기반 데모입니다. 추출 결과를 사장님이 확인하고 수정한 뒤 등록합니다.</p></section>`}
function managePage(){return `${heading('FOR SHOP OWNERS','등록 메뉴 관리','오후의 빵집 메뉴 가격과 재고를 수정하세요.')}${ownerBanner()}<div class="panel"><div class="panel-title"><h2>오늘의 메뉴</h2><span>${ownerMenus().length}개</span></div>${ownerMenus().map(m=>`<div class="manage-item"><img src="${image(m)}" alt=""><div><strong>${esc(m.name)}</strong><small>${won(m.price)} · 재고 ${m.stock}개</small></div><button class="outline-button" data-action="edit" data-id="${m.id}">수정</button></div>`).join('')||'<p class="muted">오늘 등록된 메뉴가 없습니다.</p>'}</div><p class="demo-note">수정한 내용은 현재 브라우저에 저장됩니다.</p>`}
